function applyLanguage(value){lang=value;document.documentElement.lang=lang;document.title=siteSettings.brand+(lang==='bn'?' — ক্যাম্পাসের পানি':' — Campus water');$('.intro-tagline').textContent=siteSettings['tagline_'+lang];$('.header-caption').textContent=tr('campus');$('#locations-title').innerHTML=`${esc(siteSettings['heading_'+lang])}<span>.</span>`;$('#search').placeholder=tr('search');$('#search').setAttribute('aria-label',tr('search'));$('#no-results p').textContent=tr('empty');$('#portal-login').textContent=lang==='bn'?'লগইন':'Sign in';$('#clear-search').textContent=tr('clear');$('#source-dialog .eyebrow').textContent=tr('report');$('.close').setAttribute('aria-label',tr('close'));$('.brand').setAttribute('aria-label',tr('home'));$('#language-switch').textContent=lang==='bn'?'English':'বাংলা';$('#language-switch').setAttribute('aria-label',lang==='bn'?'Switch to English':'বাংলায় দেখুন');$('#pause').title=tr(paused?'play':'pause');$('#pause').setAttribute('aria-label',tr(paused?'play':'pause'));$('#motion').title=tr(sensorsEnabled?'motionOn':'motion');$('#motion').setAttribute('aria-label',tr(sensorsEnabled?'motionOn':'motion'));if($('#nav-report-label'))$('#nav-report-label').textContent=tr('reportProblem');if($('#problems-eyebrow'))$('#problems-eyebrow').textContent=lang==='bn'?'নাগরিক রিপোর্ট':'COMMUNITY WATER REPORTS';if($('#problems-title'))$('#problems-title').innerHTML=`${esc(tr('problemsSectionTitle'))}<span>.</span>`;if($('#problems-description'))$('#problems-description').textContent=tr('problemsSectionDesc');if($('#section-report-btn-text'))$('#section-report-btn-text').textContent=tr('reportProblem');if($('#no-problems-title'))$('#no-problems-title').textContent=tr('noProblemsTitle');if($('#no-problems-text'))$('#no-problems-text').textContent=tr('noProblemsDesc');if($('#problem-dialog-title'))$('#problem-dialog-title').textContent=tr('reportProblemTitle');if($('#problem-dialog-desc'))$('#problem-dialog-desc').textContent=tr('reportProblemDesc');if($('#cancel-problem-dialog'))$('#cancel-problem-dialog').textContent=tr('cancel');if($('#submit-problem'))$('#submit-problem').innerHTML=`${tr('submitProblem')} <span>→</span>`;const setLbl=(id,txt)=>{const el=$('#'+id+' .lbl-text');if(el)el.textContent=txt;};setLbl('lbl-reporter-name',tr('reporterName'));setLbl('lbl-reporter-id',tr('reporterId'));setLbl('lbl-problem-loc',tr('problemLocation'));setLbl('lbl-problem-type',tr('problemType'));setLbl('lbl-problem-desc',tr('problemDesc'));const sel=$('#problem-form select[name="problem_type"]');if(sel&&sel.options.length){sel.options[0].textContent=tr('selectProblemType');for(let i=1;i<sel.options.length;i++){const opt=sel.options[i];if(opt.value)opt.textContent=tr(opt.value);}}const f=$('#problem-form');if(f){if(f.elements.reporter_name)f.elements.reporter_name.placeholder=lang==='bn'?'আপনার পূর্ণ নাম লিখুন':'Enter your full name';if(f.elements.reporter_id)f.elements.reporter_id.placeholder=lang==='bn'?'শিক্ষার্থী বা স্টাফ আইডি':'Enter student or staff ID';if(f.elements.location_or_source)f.elements.location_or_source.placeholder=lang==='bn'?'ভবনের নাম, তলা বা ডিসপেনসার কোড':'Building name, floor, or dispenser code';if(f.elements.description)f.elements.description.placeholder=lang==='bn'?'সমস্যার বিস্তারিত বিবরণ দিন (ঐচ্ছিক)':'Describe what you observed (optional)';}render();renderProblems();if($('#source-dialog').open)showSource(currentCode);}
$('#search').oninput=render;$('#clear-search').onclick=()=>{$('#search').value='';render();$('#search').focus()};
$('#language-switch').onclick=()=>applyLanguage(lang==='en'?'bn':'en');
document.addEventListener('keydown',e=>{if(entered&&e.key==='/'&&!/INPUT|TEXTAREA/.test(document.activeElement.tagName)&&!document.querySelector('dialog[open]')){e.preventDefault();$('#search').focus()}});
function reportHTML(r,placeholder=false){const l=locations.find(l=>l.sources.includes(currentCode));return renderReport(r,{tr:htmlTr,num,esc,code:currentCode,locationName:name(l),lang,placeholder})}
async function showSource(code){const l=locations.find(l=>l.sources.includes(code));if(!l)return;currentCode=code;const id=++requestId;
 $('#source-detail').innerHTML=`<div id="report-area"><div class="badge">${htmlTr('loading')}</div></div><div class="dialog-actions"><button class="secondary" id="copy-source">${htmlTr('copy')}</button></div>`;
 if(!$('#source-dialog').open)$('#source-dialog').showModal();$('#copy-source').onclick=async()=>{try{await navigator.clipboard.writeText(`${location.origin}${location.pathname}#source=${encodeURIComponent(code)}`);toast(tr('copied'))}catch{toast(tr('copyFallback'))}};
 let reports=[],unavailable=false;try{if(apiEnabled){const res=await fetch(`/api/sources/${encodeURIComponent(code)}/reports`);if(res.ok&&res.headers.get('content-type')?.includes('application/json'))reports=await res.json();else unavailable=true}}catch{unavailable=true}if(id!==requestId)return;
 $('#report-area').innerHTML=reports.length?`${reports.map(r=>reportHTML(r)).join('')}<p class="report-footnote">${htmlTr('caution')}</p>`:unavailable?`<div class="empty-report"><h3>${htmlTr('failed')}</h3><p>${htmlTr('error')}</p></div>`:reportHTML({screening_status:'pending'},true);
}
$('#location-list').onclick=e=>{const button=e.target.closest('[data-code]');if(button)location.hash='source='+encodeURIComponent(button.dataset.code)};
function route(){if(!entered)return;if(location.hash.startsWith('#source=')){try{showSource(decodeURIComponent(location.hash.slice(8)))}catch{toast(tr('invalid'))}}else if($('#source-dialog').open)$('#source-dialog').close()}
window.addEventListener('hashchange',route);
const dialog=$('#source-dialog');dialog.querySelector('.close').onclick=()=>dialog.close();dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});dialog.addEventListener('close',()=>{requestId++;if(location.hash.startsWith('#source='))history.replaceState(null,'','#locations')});
render();
(async()=>{if(!apiEnabled)return;try{const r=await fetch('/api/summary');if(!r.ok||!r.headers.get('content-type')?.includes('application/json'))return;const d=await r.json();summary=new Map(d.sources.map(s=>[s.source_code,s.count]));render()}catch{}})();
let problemReports=[];
async function loadProblems(){if(!apiEnabled)return;try{const res=await fetch('/api/problem-reports');if(res.ok&&res.headers.get('content-type')?.includes('application/json')){problemReports=await res.json();renderProblems()}}catch{}}
function renderProblems(){const list=$('#problems-list');if(!list)return;if(!problemReports.length){$('#no-problems').hidden=false;list.innerHTML='';return} $('#no-problems').hidden=true;list.innerHTML=problemReports.map(p=>`<article class="problem-card"><div class="problem-card-top"><span class="problem-badge ${esc(p.problem_type)}">${htmlTr(p.problem_type)}</span><span class="problem-verified">✓ ${htmlTr('verifiedStatus')}</span></div><h4>${esc(p.location_or_source)}</h4>${p.description?`<p class="problem-card-desc">${esc(p.description)}</p>`:''}<div class="problem-card-footer"><span>${htmlTr('reportedBy')}: <b>${esc(p.reporter_name)}</b> (${esc(p.reporter_id)})</span><span>${new Date(p.created_at).toLocaleDateString(lang==='bn'?'bn-BD':'en-US')}</span></div></article>`).join('');}
function populateSourcesDatalist(){const dl=$('#known-sources-list');if(!dl)return;const items=[];for(const l of locations){items.push(name(l));for(const s of (l.sources||[]))items.push(s)}dl.innerHTML=[...new Set(items)].map(v=>`<option value="${esc(v)}">`).join('');}
const pDialog=$('#problem-dialog');
function openProblemDialog(){populateSourcesDatalist();$('#problem-notice').hidden=true;pDialog.showModal();}
$('#open-problem-btn')?.addEventListener('click',openProblemDialog);
$('#section-report-btn')?.addEventListener('click',openProblemDialog);
$('#close-problem-dialog')?.addEventListener('click',()=>pDialog.close());
$('#cancel-problem-dialog')?.addEventListener('click',()=>pDialog.close());
pDialog?.addEventListener('click',e=>{if(e.target===pDialog){const r=pDialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)pDialog.close()}});
$('#problem-form')?.addEventListener('submit',async e=>{e.preventDefault();const form=e.currentTarget,btn=$('#submit-problem'),noticeEl=$('#problem-notice');btn.disabled=true;btn.textContent=tr('submitting');noticeEl.hidden=true;try{const body={reporter_name:form.elements.reporter_name.value.trim(),reporter_id:form.elements.reporter_id.value.trim(),location_or_source:form.elements.location_or_source.value.trim(),problem_type:form.elements.problem_type.value,description:form.elements.description.value.trim()};const res=await fetch('/api/problem-reports',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});const data=await res.json();if(!res.ok)throw new Error(data.error||'Failed to submit report');noticeEl.className='notice success';noticeEl.textContent=tr('problemSubmitted');noticeEl.hidden=false;form.reset();toast(tr('problemSubmitted'));setTimeout(()=>{pDialog.close();noticeEl.hidden=true},2500)}catch(err){noticeEl.className='notice error';noticeEl.textContent=err.message;noticeEl.hidden=false}finally{btn.disabled=false;btn.innerHTML=`${tr('submitProblem')} <span>→</span>`}});
loadProblems();
function enterLanguage(value){applyLanguage(value);try{localStorage.setItem('aquavita-language',value)}catch{}entered=true;$('#portal').inert=false;$('#intro').classList.add('leaving');document.body.classList.remove('intro-active');setTimeout(()=>{$('#intro').hidden=true;$('#locations-title').setAttribute('tabindex','-1');$('#locations-title').focus({preventScroll:true});route()},matchMedia('(prefers-reduced-motion: reduce)').matches?0:450)}
document.querySelectorAll('[data-language]').forEach(button=>button.onclick=()=>enterLanguage(button.dataset.language));
document.body.classList.add('intro-active');
// Lightweight canvas water: layered waves, reflected light, leaves, and touch ripples.
const canvas=$('#water'),ctx=canvas.getContext('2d'),reduced=matchMedia('(prefers-reduced-motion: reduce)');let w=0,h=0,t=0,tilt=0,targetTilt=0,energy=0,paused=reduced.matches,raf=0,last=0,ripples=[];
function resize(){const r=canvas.getBoundingClientRect();w=r.width;h=r.height;const dpr=Math.min(devicePixelRatio||1,2);canvas.width=w*dpr;canvas.height=h*dpr;ctx.setTransform(dpr,0,0,dpr,0,0);draw()}
function draw(){ctx.clearRect(0,0,w,h);const g=ctx.createLinearGradient(0,0,w,h);g.addColorStop(0,siteSettings.background);g.addColorStop(.55,'#c2dfca');g.addColorStop(1,'#77baa6');ctx.fillStyle=g;ctx.fillRect(0,0,w,h);
 for(let j=0;j<8;j++){ctx.beginPath();const base=h*(.15+j*.105);for(let x=0;x<=w+10;x+=8){const y=base+Math.sin(x/(170+j*18)+t*.6+j*.7)*(22+j*3+energy)+Math.sin(x/83-t*.4+j)*8+(x-w/2)*tilt*.18; x===0?ctx.moveTo(x,y):ctx.lineTo(x,y)}ctx.lineTo(w,h);ctx.lineTo(0,h);ctx.closePath();ctx.fillStyle=['#d1eadb60','#d9edd466','#acdac955','#99ccba50','#83bda766','#65ac9a44','#4b9e8f44','#34897640'][j];ctx.fill();ctx.strokeStyle='#f3ffe740';ctx.lineWidth=1;ctx.stroke()}
 for(let i=0;i<18;i++){const x=(w*.43+i*67+Math.sin(t*.2+i)*22)%(w+60);const y=h*.15+(i*43)%(h*.78)+Math.sin(t*.4+i)*12;ctx.beginPath();ctx.ellipse(x,y,24+i%4*9,3+i%3,Math.sin(i)*.35,0,Math.PI*2);ctx.strokeStyle='#edffe327';ctx.lineWidth=1.5;ctx.stroke()}
 // Floating botanical shapes are drawn as paired curved leaf surfaces.
 [[.82,.2,.7],[.7,.68,.4],[.95,.78,.5]].forEach(([px,py,sz],i)=>{ctx.save();ctx.translate(w*px+Math.sin(t*.35+i)*9,h*py+Math.cos(t*.3+i)*8);ctx.rotate(-.65+Math.sin(t*.15+i)*.12+tilt*.2);ctx.scale(sz,sz);ctx.shadowColor='#224d3420';ctx.shadowBlur=16;ctx.beginPath();ctx.moveTo(-44,0);ctx.bezierCurveTo(-9,-32,26,-18,48,0);ctx.bezierCurveTo(17,25,-20,27,-44,0);ctx.fillStyle='#6c96617d';ctx.fill();ctx.shadowBlur=0;ctx.beginPath();ctx.moveTo(-42,0);ctx.lineTo(43,0);ctx.strokeStyle='#e9f5c966';ctx.stroke();ctx.restore()});
 ripples=ripples.filter(r=>r.age<2.5);for(const r of ripples){for(let k=0;k<3;k++){ctx.beginPath();ctx.ellipse(r.x,r.y,10+r.age*55+k*10,4+r.age*18+k*4,0,0,Math.PI*2);ctx.strokeStyle=`rgba(247,255,236,${Math.max(0,(1-r.age/2.5)*.5-k*.1)})`;ctx.lineWidth=1.3;ctx.stroke()}}
}
function frame(now){raf=0;if(paused||document.hidden)return;const dt=Math.min((now-(last||now))/1000,.05);last=now;t+=dt;tilt+=(targetTilt-tilt)*.035;energy*=.96;for(const r of ripples)r.age+=dt;draw();raf=requestAnimationFrame(frame)}
function start(){if(!raf&&!paused&&!document.hidden){last=0;raf=requestAnimationFrame(frame)}}
$('#pause').textContent=paused?'▶':'Ⅱ';$('#pause').setAttribute('aria-label',paused?tr('play'):tr('pause'));$('#pause').title=paused?tr('play'):tr('pause');$('#pause').setAttribute('aria-pressed',String(paused));
$('#pause').onclick=()=>{paused=!paused;$('#pause').textContent=paused?'▶':'Ⅱ';$('#pause').setAttribute('aria-label',paused?tr('play'):tr('pause'));$('#pause').title=paused?tr('play'):tr('pause');$('#pause').setAttribute('aria-pressed',String(paused));if(paused){cancelAnimationFrame(raf);raf=0}else start()};
document.body.addEventListener('pointerdown',e=>{if(e.target.closest('button,a,input,summary,dialog'))return;const r=canvas.getBoundingClientRect();ripples.push({x:e.clientX-r.left,y:e.clientY-r.top,age:0});if(ripples.length>12)ripples.shift();energy=10;if(paused)draw()});
document.body.addEventListener('pointermove',e=>{if(e.pointerType==='mouse'){const r=canvas.getBoundingClientRect();targetTilt=(e.clientX-r.left)/w-.5}});
let sensorsEnabled=false;
$('#motion').onclick=async()=>{if(sensorsEnabled){toast(tr('sensorOn'));return}try{if(!window.DeviceOrientationEvent&&!window.DeviceMotionEvent){toast(tr('sensorMissing'));return}for(const api of [window.DeviceOrientationEvent,window.DeviceMotionEvent]){if(typeof api?.requestPermission==='function'&&await api.requestPermission()!=='granted'){toast(tr('sensorDenied'));return}}
 window.addEventListener('deviceorientation',e=>{if(e.gamma!=null){targetTilt=Math.max(-1,Math.min(1,e.gamma/35));$('#motion').classList.add('enabled');$('#motion').setAttribute('aria-label',tr('tiltOn'))}});
 window.addEventListener('devicemotion',e=>{const a=e.acceleration;if(a&&Math.hypot(a.x||0,a.y||0,a.z||0)>6){energy=25;ripples.push({x:w*.7,y:h*.7,age:0});if(ripples.length>12)ripples.shift()}});sensorsEnabled=true;$('#motion').classList.add('enabled');$('#motion').setAttribute('aria-label',tr('motionOn'));toast(tr('sensorReady'));}catch{toast(tr('sensorError'))}};
new ResizeObserver(resize).observe(canvas);document.addEventListener('visibilitychange',()=>{if(document.hidden){cancelAnimationFrame(raf);raf=0}else start()});reduced.addEventListener('change',e=>{if(e.matches&&!paused)$('#pause').click()});resize();start();

